+        }
+    }
+
+    freshThreads.forEach(function(t) {
+        if (!t || t.resolved === true) return;
+        var isAddressed =
+            (t.threadId && (byThreadId[String(t.threadId)] || cited.indexOf(String(t.threadId)) !== -1)) ||
