                threads: [
                    { index: 1, rootCommentId: 7770002, threadId: 'PRRT_snapshot_2', resolved: false, body: 'fix' }
                ]
            })
        });

        loaded.mod.postThreadReplies(loaded.scm, '123', { ticketKey: 'PROJ-123' });

