            // inside the review conversation, not as a new top-level PR comment.
            try {
                scm.replyToThread(pullRequestId, thread, replyText);
                console.log('✅ Replied to comment #' + inReplyToId);
                posted++;
            } catch (e) {
                console.warn('Failed to post reply:', e.message || e);
            }
        } else {
