        citedThreadIds: extractCitedThreadIds(outputOptions.responseText),
        addressedThreadIds: addressed.threadIds,
        addressedRootIds: addressed.rootIds
    });

    console.log('Posted ' + posted + '/' + replies.length + ' thread replies');
    return posted;
}

