        extractTicketKey: realTrackers.extractTicketKey
    };
}

function loadPushReworkChangesModule(fileMap, opts) {
    opts = opts || {};
    var outputFiles = makeOutputFiles(fileMap);
    var replyCalls = [];
    var resolveCalls = [];
    var addCommentCalls = [];
