/**
 * Shared helpers for reading agent output artifacts.
 *
 * Normalization order for output files:
 * 1) outputs/<name>
 * 2) outputs/<ticketKey>/<name>                (if ticketKey provided)
 * 3) <workingDir>/outputs/<name>               (if workingDir provided)
 * 4) <workingDir>/outputs/<ticketKey>/<name>   (if workingDir + ticketKey provided)
 *
 * For absolute paths we read the path as-is.
 */

function readRaw(path) {
    if (!path) return null;
    try {
        var content = file_read({ path: path });
        if (content && content.toString().trim()) {
            return content;
        }
    } catch (e) {}
    return null;
}

function normalizeToOutputsPath(pathOrName) {
    if (!pathOrName) return '';
    if (pathOrName.indexOf('outputs/') === 0) return pathOrName;
    if (pathOrName.indexOf('/') === -1) return 'outputs/' + pathOrName;
    return pathOrName;
}

function buildOutputCandidates(pathOrName, options) {
    var opts = options || {};
    var ticketKey = opts.ticketKey;
    var workingDir = opts.workingDir;
    var normalized = normalizeToOutputsPath(pathOrName);
    var candidates = [];

    // Absolute path: use as-is first, then (optionally) also workingDir prefix if provided by caller path.
    if (normalized.indexOf('/') === 0) {
        candidates.push(normalized);
        return candidates;
    }

    candidates.push(normalized);

    if (normalized.indexOf('outputs/') === 0 && ticketKey) {
        var outputName = normalized.substring('outputs/'.length);
        candidates.push('outputs/' + ticketKey + '/' + outputName);
    }

    if (workingDir) {
        candidates.push(workingDir + '/' + normalized);
        if (normalized.indexOf('outputs/') === 0 && ticketKey) {
            var outputNameInWd = normalized.substring('outputs/'.length);
            candidates.push(workingDir + '/outputs/' + ticketKey + '/' + outputNameInWd);
        }
    }

    return candidates;
}

function readOutputFile(pathOrName, options) {
    var candidates = buildOutputCandidates(pathOrName, options);
    for (var i = 0; i < candidates.length; i++) {
        var content = readRaw(candidates[i]);
        if (content) {
            return content;
        }
    }
    return null;
}

function readOutputFileDetailed(pathOrName, options) {
    var candidates = buildOutputCandidates(pathOrName, options);
    for (var i = 0; i < candidates.length; i++) {
        var content = readRaw(candidates[i]);
        if (content) {
            return { content: content, path: candidates[i] };
        }
    }
    return null;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        normalizeToOutputsPath: normalizeToOutputsPath,
        buildOutputCandidates: buildOutputCandidates,
        readOutputFile: readOutputFile,
        readOutputFileDetailed: readOutputFileDetailed
    };
}

}

/**
 * Write PR context files to input folder.
 * Writes: pr_info.md, pr_diff.txt, pr_discussions.md, pr_discussions_raw.json
 *
 * @param {string}      inputFolder  - input/{ticketKey} path
 * @param {Object}      prDetails    - PR object (GitHub or GitLab, normalized)
 * @param {string}      diff         - git diff text
 * @param {string|null} markdown     - discussions markdown (from githubHelpers.fetchDiscussionsAndRawData)
 * @param {Object|null} rawThreads   - raw threads with IDs (from githubHelpers.fetchDiscussionsAndRawData)
 */
function writePRContext(inputFolder, prDetails, diff, markdown, rawThreads) {
    // pr_info.md
    let prInfo = '# Pull Request Information\n\n';
    prInfo += '- **PR #**: ' + prDetails.number + '\n';
    prInfo += '- **URL**: ' + prDetails.html_url + '\n';
    prInfo += '- **Title**: ' + prDetails.title + '\n';
    prInfo += '- **Author**: ' + (prDetails.user ? prDetails.user.login : 'unknown') + '\n';
    prInfo += '- **Branch**: `' + (prDetails.head ? prDetails.head.ref : 'unknown') +
              '` → `' + (prDetails.base ? prDetails.base.ref : 'unknown') + '`\n';
    prInfo += '- **State**: ' + prDetails.state + '\n';
    prInfo += '- **Files Changed**: ' + (prDetails.changed_files || 0) + '\n';
    prInfo += '- **Additions**: +' + (prDetails.additions || 0) + '\n';
    prInfo += '- **Deletions**: -' + (prDetails.deletions || 0) + '\n';
    prInfo += '- **Created**: ' + (prDetails.created_at || '') + '\n';
    prInfo += '- **Updated**: ' + (prDetails.updated_at || '') + '\n';
    if (prDetails.body) {
        prInfo += '\n## PR Description\n\n' + prDetails.body + '\n';
    }
    writeInputFile(inputFolder + '/pr_info.md', prInfo, 'pr_info.md');

    // pr_diff.txt
    var diffContext = trimLargeTextForInput(diff || 'No diff available', 'PR Diff', MAX_PR_DIFF_CONTEXT_CHARS);
    writeInputFile(inputFolder + '/pr_diff.txt', diffContext, 'pr_diff.txt');

    // pr_discussions.md
    if (markdown) {
        writeInputFile(inputFolder + '/pr_discussions.md', markdown, 'pr_discussions.md');
    }

    // pr_discussions_raw.json
    if (rawThreads) {
        writeInputFile(
            inputFolder + '/pr_discussions_raw.json',
            JSON.stringify(rawThreads, null, 2),
            'pr_discussions_raw.json (' + rawThreads.threads.length + ' threads)'
        );
    }

    console.log('✅ PR context written to', inputFolder);
}

